"""Install manual refresh feedback; never launches a real refresh."""
import os,json,base64,hashlib,fcntl,subprocess,time,tempfile,pwd
from pathlib import Path
MANIFEST={'phone_ui.py': {'old': 'dc67c334790ff42787e0203bf05ee50459d75c0904dd3e273f70105e46301479', 'new': 'baf6bfef2807c67365352c797a59aa4d74b9778fbb8159c8f7d519af35572ad1', 'body': ''}, 'phone_view.py': {'old': 'ebb01f8a98e6249750a548af341ff11bca562e9159781c6922a3341b68b7b7b7', 'new': '11db5485c2bf26324342018d62f3cb8a2fc58ba6e3f0d815bdbd7fb8f7fd6acd', 'body': ''}, 'runner.py': {'old': '2b12667784a8cb50d833a63690e9bb5c01cc4c77045769be38744ed1eedf7c3d', 'new': '4594a6e2026795448ef615f0e37d49622d95cc39af2ecded938380f301dc6c0d', 'body': ''}, 'test_phone_view.py': {'old': '9094c1e52c1196dc87069d3d20ebf7c27907859919328614e9d767335f4ef80b', 'new': 'f2be8f283a709997450bc90f1ccaf6b68e92d70572ec4dc6824e9eed7bb80eb8', 'body': ''}, 'refresh_receipts.py': {'old': None, 'new': '720f0d8e69989a5edea838a03b73f703a08fc6595293f930c253480d278f9657', 'body': ''}, 'test_refresh_receipts.py': {'old': None, 'new': '986edfed0514bbd7872a03ef3ffb1eed81934bdb3ccbd2ce2cc7fbc9f4ef29a6', 'body': ''}}
def replace(p,raw,stat=None):
    fd,name=tempfile.mkstemp(dir=p.parent,prefix='.refresh-install-')
    try:
        with os.fdopen(fd,'wb') as f:
            f.write(raw);f.flush();os.fsync(f.fileno());os.fchmod(f.fileno(),stat.st_mode&0o777 if stat else 0o644)
            if stat:os.fchown(f.fileno(),stat.st_uid,stat.st_gid)
        os.replace(name,p)
    finally:Path(name).unlink(missing_ok=True)
def main():
    assert os.geteuid()==0,'Root required'
    root=Path('/opt/fh6/repo/automation/server');store=Path('/var/lib/fh6')
    prepared={}
    for n,m in MANIFEST.items():
        p=root/n;assert not p.is_symlink(),'Unexpected symlink'
        before=p.read_bytes() if p.exists() else None
        sha=hashlib.sha256(before).hexdigest() if before is not None else None
        assert sha==m['old'],'Unexpected version: '+n+'; nothing changed'
        raw=base64.b64decode(m['body']);assert hashlib.sha256(raw).hexdigest()==m['new'];compile(raw,str(p),'exec')
        prepared[n]=(before,p.stat() if p.exists() else None,raw)
    lockpath=store/'runner.lock';assert not lockpath.is_symlink()
    with lockpath.open('rb') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        subprocess.run(['systemctl','is-active','--quiet','fh6-phone.service'],check=True)
        backup=store/'repairs'/('refresh-feedback-'+str(time.time_ns()));backup.mkdir(mode=0o700)
        for n,(before,stat,raw) in prepared.items():
            if before is not None:
                saved=backup/n;saved.write_bytes(before);saved.chmod(0o600)
        subprocess.run(['systemctl','stop','fh6-phone.service'],check=True)
        applied=[]
        try:
            for n,(before,stat,raw) in prepared.items():replace(root/n,raw,stat);applied.append(n)
            subprocess.run(['/usr/bin/python3','-m','unittest','test_phone_view','test_phone_csrf','test_refresh_receipts','test_server'],cwd=root,check=True,timeout=90)
            subprocess.run(['systemctl','start','fh6-phone.service'],check=True)
            subprocess.run(['systemctl','is-active','--quiet','fh6-phone.service'],check=True)
        except Exception:
            for n in reversed(applied):
                before,stat,_=prepared[n]
                if before is None:(root/n).unlink(missing_ok=True)
                else:replace(root/n,before,stat)
            subprocess.run(['systemctl','start','fh6-phone.service'],check=True)
            raise
        print('REFRESH_FEEDBACK_INSTALLED request acceptance, explicit worker binding, stage history; no real refresh queued',flush=True)
        print('BACKUP='+str(backup),flush=True)
if __name__=='__main__':main()
